                    </div>
                    <div>
                      <h4 className="text-3xl font-serif text-wild-lime font-bold">30+</h4>
                      <p className="text-xs text-gray-500 uppercase tracking-widest mt-1">Leopard Population</p>
                    </div>
                    <div>
                      <h4 className="text-3xl font-serif text-wild-lime font-bold">60+</h4>
