import { GoogleGenAI, Type, Modality } from "@google/genai";

// Guideline: Create a new GoogleGenAI instance right before making an API call to ensure current API key.
// Guideline: Always use { apiKey: process.env.API_KEY }.

export const safariChat = async (message: string, history: any[] = []) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const chat = ai.chats.create({
    model: 'gemini-3-pro-preview',
    // Guideline: History is passed to the create method
    history: history,
    config: {
      systemInstruction: "You are the Wilpattu Wild Camping Assistant. You are an expert on Sri Lankan wildlife, Wilpattu National Park, and luxury safari experiences. Be professional, inviting, and highly informative. If asked about locations, use Google Search tools. If the query is complex, use your thinking budget.",
      thinkingConfig: { thinkingBudget: 32768 },
      tools: [{ googleSearch: {} }]
    }
  });

  const response = await chat.sendMessage({ message });
  return {
    text: response.text,
    grounding: response.candidates?.[0]?.groundingMetadata?.groundingChunks
  };
};

export const analyzeWildlife = async (base64Image: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
        { text: "Identify this wildlife species found in Wilpattu. Provide name, habitat, a fun fact, and conservation status in JSON format." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          species: { type: Type.STRING },
          description: { type: Type.STRING },
          habitat: { type: Type.STRING },
          funFact: { type: Type.STRING },
          conservationStatus: { type: Type.STRING }
        },
        required: ["species", "description", "habitat", "funFact", "conservationStatus"]
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

export const generateSafariImage = async (prompt: string, aspectRatio: string = "16:9") => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts: [{ text: `A photorealistic high-quality image of ${prompt} in the wild jungles of Wilpattu National Park, Sri Lanka.` }] },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any,
        imageSize: "1K"
      }
    }
  });

  // Guideline: Iterate through all parts to find the image part, do not assume it's the first.
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  return null;
};

export const speakText = async (text: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Say in a warm, professional safari guide voice: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  return base64Audio || null;
};

export const transcribeAudio = async (base64Audio: string) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'audio/pcm;rate=16000', data: base64Audio } },
          { text: "Transcribe this audio safari log precisely." }
        ]
      }
    });
    return response.text;
};

export const searchNearbyPlaces = async (lat: number, lng: number) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: "What are the best places to visit near Wilpattu National Park?",
        config: {
          tools: [{googleMaps: {}}],
          toolConfig: {
            retrievalConfig: {
              latLng: {
                latitude: lat,
                longitude: lng
              }
            }
          }
        },
    });
    return {
        text: response.text,
        links: response.candidates?.[0]?.groundingMetadata?.groundingChunks
    };
};

import React, { useState, useRef, useEffect } from 'react';
import { safariChat, speakText } from '../services/geminiService';
import { ChatMessage } from '../types';

// Manual Base64 decode function as per guidelines
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Manual PCM audio decoding function as per guidelines
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const Chatbot: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Ayubowan! I am your Wilpattu Safari Assistant. How can I help you plan your wilderness adventure today?' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setLoading(true);

    try {
      // Guideline: Prepare history for the service call
      const chatHistory = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
      }));

      const response = await safariChat(userMsg, chatHistory);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: response.text || '',
        grounding: response.grounding
      }]);
    } catch (error) {
        console.error(error);
      setMessages(prev => [...prev, { role: 'model', text: "Forgive me, my connection to the jungle is weak. Please try again." }]);
    } finally {
      setLoading(false);
    }
  };

  const handleSpeak = async (text: string) => {
    try {
      const audioBase64 = await speakText(text);
      if (audioBase64) {
        if (!audioContextRef.current) {
          // @ts-ignore
          audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const audioData = decodeBase64(audioBase64);
        const audioBuffer = await decodeAudioData(audioData, ctx, 24000, 1);

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) {
      console.error(e);
      alert("Error playing audio guide.");
    }
  };

  return (
    <div className="bg-wild-green/30 backdrop-blur-xl rounded-3xl border border-white/10 flex flex-col h-[600px] shadow-2xl overflow-hidden text-white">
      <div className="bg-wild-green p-4 flex items-center justify-between border-b border-white/10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-wild-lime/20 flex items-center justify-center">
            <i className="fa-solid fa-sparkles text-wild-lime"></i>
          </div>
          <div>
            <h3 className="font-bold text-white leading-none">Safari AI Guide</h3>
            <span className="text-[10px] text-wild-lime font-bold uppercase tracking-widest">Active Intelligence</span>
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-2xl relative ${
              m.role === 'user' ? 'bg-wild-lime text-black rounded-tr-none' : 'bg-white/10 text-white rounded-tl-none'
            }`}>
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{m.text}</p>

              {/* Guideline: Extract website URLs from groundingChunks and list them */}
              {m.grounding && m.grounding.length > 0 && (
                <div className="mt-3 pt-3 border-t border-white/10 space-y-2">
                  <span className="text-[10px] uppercase font-bold text-wild-lime block">Sources:</span>
                  {m.grounding.map((chunk, j) => (
                    <a 
                      key={j} 
                      href={chunk.web?.uri || chunk.maps?.uri} 
                      target="_blank" 
                      rel="noreferrer"
                      className="block text-[10px] text-blue-400 hover:underline truncate"
                    >
                      <i className="fa-solid fa-link mr-1"></i>
                      {chunk.web?.title || chunk.maps?.title || "Learn more"}
                    </a>
                  ))}
                </div>
              )}

              {m.role === 'model' && (
                <button 
                  onClick={() => handleSpeak(m.text)}
                  className="mt-2 text-[10px] uppercase font-bold text-wild-lime hover:text-white transition-colors flex items-center gap-1"
                >
                  <i className="fa-solid fa-volume-high"></i> Listen
                </button>
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-white/5 p-4 rounded-2xl rounded-tl-none flex gap-2">
              <div className="w-2 h-2 bg-wild-lime rounded-full animate-bounce"></div>
              <div className="w-2 h-2 bg-wild-lime rounded-full animate-bounce delay-100"></div>
              <div className="w-2 h-2 bg-wild-lime rounded-full animate-bounce delay-200"></div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-black/20 border-t border-white/10 flex gap-2">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Ask about leopards, camping, or the park..."
          className="flex-1 bg-white/5 border border-white/10 rounded-full px-5 py-3 text-sm focus:outline-none focus:border-wild-lime text-white"
        />
        <button 
          onClick={handleSend}
          className="w-12 h-12 bg-wild-lime text-black rounded-full flex items-center justify-center hover:scale-105 transition-transform"
        >
          <i className="fa-solid fa-paper-plane"></i>
        </button>
      </div>
    </div>
  );
};

