import React, { useEffect, useState } from 'react';
import { LOGO_SVG } from '../constants';

const Preloader: React.FC = () => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 100) {
          clearInterval(interval);
          return 100;
        }
        return prev + 1;
      });
    }, 20);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="fixed inset-0 z-[100] bg-[#0d1a15] flex flex-col items-center justify-center">
      <div className="w-32 h-32 mb-8 animate-pulse">
        {LOGO_SVG}
      </div>
      <div className="w-64 h-1 bg-white/10 rounded-full overflow-hidden relative">
        <div 
          className="absolute inset-y-0 left-0 bg-wild-lime transition-all duration-300 ease-out"
          style={{ width: `${progress}%` }}
        ></div>
      </div>
      <div className="mt-4 text-wild-lime font-bold tracking-[0.3em] text-xs uppercase">
        Entering the Wild... {progress}%
      </div>
    </div>
  );
};

export default Preloader;

