import { AppSection, WildlifeAnalysis } from './types';
import { SAFARI_PACKAGES, LOGO_SVG } from './constants';
import { analyzeWildlife, generateSafariImage, searchNearbyPlaces } from './services/geminiService';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState<AppSection>(AppSection.HOME);
  const [isLoading, setIsLoading] = useState(true);
  const [imagePrompt, setImagePrompt] = useState('');
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [genImage, setGenImage] = useState<string | null>(null);
  const [generating, setGenerating] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<WildlifeAnalysis | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [nearbyInfo, setNearbyInfo] = useState<{text: string, links: any[]} | null>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [activeSection]);

  const handleAvailabilityCheck = (inDate: string, outDate: string, guestCount: string) => {
    // Navigate to booking and pass the context (simulated for now)
    setActiveSection(AppSection.BOOKING);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setAnalyzing(true);
    setAnalysisResult(null);

    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const result = await analyzeWildlife(base64);
        setAnalysisResult(result);
      } catch (err) {
        alert("Failed to analyze image. Ensure it's a clear photo of wildlife.");
      } finally {
        setAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleGenerate = async () => {
    if (!imagePrompt) return;

    // @ts-ignore
    if (typeof window.aistudio !== 'undefined') {
      // @ts-ignore
      if (!(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    }

    setGenerating(true);
    try {
      const img = await generateSafariImage(imagePrompt, aspectRatio);
      setGenImage(img);
    } catch (err) {
      if (err instanceof Error && err.message.includes("Requested entity was not found.")) {
        // @ts-ignore
        if (typeof window.aistudio !== 'undefined') await window.aistudio.openSelectKey();
      }
      alert("AI artist is resting. Try again soon.");
    } finally {
      setGenerating(false);
    }
  };

  const handleFetchNearby = async () => {
    const result = await searchNearbyPlaces(8.4357, 80.0076);
    setNearbyInfo(result);
  };

  if (isLoading) {
    return <Preloader />;
  }

  return (
    <div className="min-h-screen bg-[#0d1a15] text-white">
      <Navbar activeSection={activeSection} setActiveSection={setActiveSection} />

      {activeSection === AppSection.HOME && (
        <>
          <Hero onStart={setActiveSection} />
          <AvailabilityBar onCheck={handleAvailabilityCheck} />

          {/* Welcome Section */}
