interface NavbarProps {
  activeSection: AppSection;
  setActiveSection: (section: AppSection) => void;
}

const Navbar: React.FC<NavbarProps> = ({ activeSection, setActiveSection }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { id: AppSection.HOME, label: 'HOME' },
    { id: AppSection.ABOUT, label: 'ABOUT US' },
    { id: AppSection.SAFARI, label: 'DISCOVER' },
    { id: AppSection.AI_TOOLS, label: 'AI LAB' },
    { id: AppSection.HOME, label: 'BLOG' },
    { id: AppSection.BOOKING, label: 'CONTACT US' },
