                className={`text-[11px] xl:text-[12px] font-bold tracking-[0.2em] transition-all uppercase relative group ${
                  activeSection === item.id ? 'text-luxury-tan' : 'text-white/90 hover:text-white'
                }`}
              >
                {item.label}
