    checkIn: '2026-02-16',
    checkOut: '2026-02-18',
    adults: 1,
    children: 0
  });

  const carouselRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

