    const left = (activeAccomm - 1 + ACCOMM_IMAGES.length) % ACCOMM_IMAGES.length;
    const center = activeAccomm;
    const right = (activeAccomm + 1) % ACCOMM_IMAGES.length;
    return [left, center, right];
