  const handlePrevAccomm = () => setActiveAccomm(prev => (prev - 1 + ACCOMM_IMAGES.length) % ACCOMM_IMAGES.length);
  const handleNextAccomm = () => setActiveAccomm(prev => (prev + 1) % ACCOMM_IMAGES.length);

