import React, { useState, useRef, useEffect } from 'react';

interface AvailabilityBarProps {
  initialCheckIn?: string;
  initialCheckOut?: string;
  initialAdults?: number;
  initialChildren?: number;
  onCheck: (checkIn: string, checkOut: string, adults: number, children: number) => void;
}

const AvailabilityBar: React.FC<AvailabilityBarProps> = ({ 
  initialCheckIn, 
  initialCheckOut, 
  initialAdults = 1, 
  initialChildren = 0, 
  onCheck 
}) => {
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  // Parse initial dates or use defaults
  const parseDate = (dateStr?: string) => dateStr ? new Date(dateStr) : null;

  const [startDate, setStartDate] = useState<Date | null>(parseDate(initialCheckIn) || new Date(2026, 1, 16));
  const [endDate, setEndDate] = useState<Date | null>(parseDate(initialCheckOut) || new Date(2026, 1, 18));
  const [adults, setAdults] = useState(initialAdults);
  const [children, setChildren] = useState(initialChildren);

  const calendarRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target as Node)) {
        setIsCalendarOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const formatDate = (date: Date | null) => {
    if (!date) return '';
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getDaysInMonth = (year: number, month: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (year: number, month: number) => {
    return new Date(year, month, 1).getDay();
  };

  const MonthCalendar = ({ year, month, title }: { year: number, month: number, title: string }) => {
    const days = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);
    const daysArray = [];

    for (let i = 0; i < firstDay; i++) {
      daysArray.push(null);
    }
    for (let i = 1; i <= days; i++) {
      daysArray.push(new Date(year, month, i));
    }

    const isSelected = (date: Date) => {
      if (startDate && date.toDateString() === startDate.toDateString()) return 'start';
      if (endDate && date.toDateString() === endDate.toDateString()) return 'end';
      if (startDate && endDate && date > startDate && date < endDate) return 'range';
      return null;
    };

    return (
      <div className="w-full">
        <h4 className="text-center font-bold text-[#382F2B] mb-6 uppercase tracking-widest text-[13px]">{title}</h4>
        <div className="grid grid-cols-7 text-center text-[10px] font-bold text-[#382F2B]/40 mb-4">
          {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => <div key={d}>{d}</div>)}
        </div>
        <div className="grid grid-cols-7 gap-y-1">
          {daysArray.map((date, i) => {
            if (!date) return <div key={`empty-${i}`} className="h-10"></div>;
            const status = isSelected(date);

            return (
              <div 
                key={i} 
                className={`h-10 flex items-center justify-center text-xs cursor-pointer relative ${
                  status === 'start' ? 'bg-[#382F2B] text-white' :
                  status === 'end' ? 'bg-[#382F2B] text-white' :
                  status === 'range' ? 'bg-[#EEE] text-[#382F2B]' :
                  'text-[#382F2B]/80 hover:bg-gray-100'
                }`}
                onClick={() => {
                  if (!startDate || (startDate && endDate)) {
                    setStartDate(date);
                    setEndDate(null);
                  } else {
                    if (date < startDate) {
                      setStartDate(date);
                      setEndDate(null);
                    } else {
                      setEndDate(date);
                    }
                  }
                }}
              >
                {date.getDate()}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="w-full bg-[#382F2B] py-16 lg:py-20 px-6 relative z-50">
      <div className="container mx-auto max-w-7xl flex flex-col lg:flex-row items-center gap-12 lg:gap-16">
        <div className="text-left w-full lg:w-1/4 shrink-0">
          <div className="flex items-center gap-4 mb-3">
            <div className="w-10 h-[1.5px] bg-white/40"></div>
            <span className="text-[10px] font-bold tracking-[0.4em] uppercase text-white/50">MAKE RESERVATION</span>
          </div>
          <h2 className="text-4xl md:text-5xl lg:text-6xl font-serif text-white leading-tight">Book Your Stay</h2>
        </div>

        <div className="flex flex-col md:flex-row items-end gap-6 w-full lg:w-3/4 relative">
          <div className="flex-1 w-full min-w-[280px] relative">
            <label className="text-[10px] font-bold tracking-[0.3em] uppercase block mb-4 text-white/40">DATE</label>
            <div 
              onClick={() => setIsCalendarOpen(!isCalendarOpen)}
              className="border border-white/20 h-20 p-6 flex items-center justify-between group hover:border-luxury-tan transition-all cursor-pointer bg-transparent"
            >
              <span className="text-2xl font-serif text-white/90">
                {startDate ? `${formatDate(startDate)} - ${formatDate(endDate) || '...'}` : 'Select Dates'}
              </span>
            </div>

            {isCalendarOpen && (
              <div 
                ref={calendarRef}
                className="absolute top-full mt-2 left-0 w-full md:w-[700px] bg-white shadow-[0_30px_60px_rgba(0,0,0,0.4)] p-8 md:p-10 z-[100] animate-fade-in-down"
              >
                <div className="flex items-center justify-between mb-8 border-b border-gray-100 pb-6">
                  <div className="text-[10px] font-bold tracking-[0.2em] text-[#382F2B]/60 uppercase">
                    YOUR STAY: <span className="text-[#382F2B]">{formatDate(startDate)} - {formatDate(endDate)}</span> ({startDate && endDate ? Math.ceil((endDate.getTime() - startDate.getTime()) / (1000 * 3600 * 24)) : 0} NIGHTS)
                  </div>
                  <button 
                    onClick={() => setIsCalendarOpen(false)}
                    className="bg-[#382F2B] text-white text-[9px] font-bold py-2 px-6 tracking-widest uppercase hover:bg-[#C19A74] transition-all"
                  >
                    CLOSE
                  </button>
                </div>

                <div className="flex flex-col md:flex-row gap-12 md:gap-16">
                  <MonthCalendar year={2026} month={1} title="FEBRUARY 2026" />
                  <div className="hidden md:block w-[1px] bg-gray-100 self-stretch"></div>
                  <MonthCalendar year={2026} month={2} title="MARCH 2026" />
                </div>
              </div>
            )}
          </div>

          <div className="w-full md:w-36">
            <label className="text-[10px] font-bold tracking-[0.3em] uppercase block mb-4 text-white/40">ADULTS</label>
            <div className="border border-white/20 h-20 p-6 flex items-center justify-between group hover:border-luxury-tan transition-all bg-transparent">
              <span className="text-5xl font-serif text-white leading-none">{adults}</span>
              <div className="flex flex-col gap-3">
                <button onClick={() => setAdults(prev => prev + 1)} className="text-white/30 hover:text-white transition-colors text-xs">
                  <i className="fa-solid fa-chevron-up"></i>
                </button>
                <button onClick={() => setAdults(prev => Math.max(1, prev - 1))} className="text-white/30 hover:text-white transition-colors text-xs">
                  <i className="fa-solid fa-chevron-down"></i>
                </button>
              </div>
            </div>
          </div>

          <div className="w-full md:w-36">
            <label className="text-[10px] font-bold tracking-[0.3em] uppercase block mb-4 text-white/40">CHILDREN</label>
            <div className="border border-white/20 h-20 p-6 flex items-center justify-between group hover:border-luxury-tan transition-all bg-transparent">
              <span className="text-5xl font-serif text-white leading-none">{children}</span>
              <div className="flex flex-col gap-3">
                <button onClick={() => setChildren(prev => prev + 1)} className="text-white/30 hover:text-white transition-colors text-xs">
                  <i className="fa-solid fa-chevron-up"></i>
                </button>
                <button onClick={() => setChildren(prev => Math.max(0, prev - 1))} className="text-white/30 hover:text-white transition-colors text-xs">
                  <i className="fa-solid fa-chevron-down"></i>
                </button>
              </div>
            </div>
          </div>

          <button 
            onClick={() => onCheck(formatDate(startDate), formatDate(endDate), adults, children)}
            className="h-20 bg-luxury-tan px-10 text-[11px] font-bold tracking-[0.3em] uppercase hover:bg-white hover:text-[#382F2B] transition-all whitespace-nowrap shadow-xl text-white w-full md:w-auto mt-6 md:mt-0"
          >
            CHECK AVAILABILITY
          </button>
        </div>
      </div>
    </div>
  );
};

