import React, { useState, useMemo } from 'react';
import AvailabilityBar from './AvailabilityBar';
import { SelectedRoom } from '../types';

interface BookingSelectionProps {
  checkIn: string;
  checkOut: string;
  adults: number;
  childrenCount: number;
  onUpdateParams: (checkIn: string, checkOut: string, adults: number, children: number) => void;
  onProceed: (rooms: SelectedRoom[]) => void;
}

const PLANS = [
  { id: 'plan1', name: 'Breakfast Included', price: 364 },
  { id: 'plan2', name: 'Breakfast & Lunch Included', price: 394 },
  { id: 'plan3', name: 'Full Board (B, L, D)', price: 422 },
  { id: 'plan4', name: 'All-inclusive Luxury', price: 754 },
];

const BookingSelection: React.FC<BookingSelectionProps> = ({ 
  checkIn, 
  checkOut, 
  adults, 
  childrenCount,
  onUpdateParams,
  onProceed
}) => {
  const [roomCounts, setRoomCounts] = useState<{ [key: string]: number }>({
    'plan1': 0,
    'plan2': 0,
    'plan3': 0,
    'plan4': 0,
  });

  const handleRoomChange = (plan: string, val: number) => {
    setRoomCounts(prev => ({ ...prev, [plan]: Math.max(0, val) }));
  };

  const totalRoomsSelected = useMemo(() => {
    return Object.values(roomCounts).reduce((acc: number, curr: number) => acc + curr, 0);
  }, [roomCounts]);

  const calculateNights = () => {
    const start = new Date(checkIn);
    const end = new Date(checkOut);
    const diffTime = Math.abs(end.getTime() - start.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const nights = calculateNights();

  const maxCapacity = totalRoomsSelected * 2;
  const isCapacitySufficient = maxCapacity >= adults;
  const showWarning = totalRoomsSelected > 0 && !isCapacitySufficient;

  const handleProceedClick = () => {
    const selectedRooms: SelectedRoom[] = PLANS.map(p => ({
      planId: p.id,
      name: p.name,
      price: p.price,
      count: roomCounts[p.id]
    })).filter(r => r.count > 0);

    onProceed(selectedRooms);
  };

  const RoomInput = ({ value, onChange }: { value: number, onChange: (val: number) => void }) => (
    <input 
      type="number" 
      min="0" 
      value={value} 
      onChange={(e) => onChange(parseInt(e.target.value) || 0)} 
      className="w-20 bg-[#1A1614] border border-white/10 p-3 text-center text-xl font-serif text-white focus:outline-none focus:border-luxury-tan transition-all shadow-inner"
    />
  );

  return (
    <div className="min-h-screen bg-[#F9F7F5] text-[#382F2B]">
      {/* Hero Section */}
      <section className="relative h-[50vh] w-full flex items-center justify-center overflow-hidden pt-20">
        <div className="absolute inset-0 z-0">
          <img 
            src="https://images.unsplash.com/photo-1547407139-3c921a66005c?auto=format&fit=crop&q=80&w=2400" 
            className="w-full h-full object-cover"
            alt="Leopard Wilpattu"
          />
          <div className="absolute inset-0 bg-black/30"></div>
        </div>

        <div className="container mx-auto px-4 z-10 text-center text-white mt-10">
          <h1 className="text-5xl md:text-7xl font-serif mb-4 drop-shadow-lg">
            Select Package
          </h1>
          <div className="flex items-center justify-center gap-4 text-[10px] font-bold tracking-[0.4em] uppercase opacity-80">
            <span>HOME</span>
            <span className="opacity-40">/</span>
            <span className="text-luxury-tan">WILPATTU</span>
          </div>
        </div>
      </section>

      {/* Embedded Availability Bar */}
      <div className="relative z-20">
         <AvailabilityBar 
           initialCheckIn={checkIn}
           initialCheckOut={checkOut}
           initialAdults={adults}
           initialChildren={childrenCount}
           onCheck={onUpdateParams} 
         />
      </div>

      {/* Policy Banner */}
      <div className="bg-[#382F2B] text-white py-4 border-y border-white/10">
        <div className="container mx-auto px-6 max-w-7xl flex flex-wrap items-center justify-center gap-8 text-[11px] font-bold tracking-widest uppercase">
           <div className="flex items-center gap-2">
             <i className="fa-solid fa-circle-info text-luxury-tan"></i>
             <span>Max 2 Adults per Room</span>
           </div>
           <div className="flex items-center gap-2">
             <i className="fa-solid fa-child text-luxury-tan"></i>
             <span>Children under 5 stay free with parents</span>
           </div>
           <div className="flex items-center gap-2 text-luxury-tan">
             <i className="fa-solid fa-mug-hot"></i>
             <span>Free Breakfast & Extra Bed for Child</span>
           </div>
        </div>
      </div>

      {/* Main Selection Content */}
      <section className="py-16 md:py-24">
        <div className="container mx-auto px-6 max-w-7xl">
          {showWarning && (
            <div className="mb-8 p-6 bg-red-50 border-l-4 border-red-500 text-red-800 flex items-start gap-4 animate-fade-in-down">
              <i className="fa-solid fa-triangle-exclamation text-xl mt-1"></i>
              <div>
                <h4 className="font-bold text-sm uppercase tracking-wider mb-1">Insufficient Capacity</h4>
                <p className="text-xs opacity-80 leading-relaxed">
                  You have {adults} adults but your current room selection only accommodates {maxCapacity} people. 
                  Please select at least {Math.ceil(adults / 2)} rooms to proceed.
                </p>
              </div>
            </div>
          )}

          <div className="flex flex-col lg:flex-row gap-8">

            {/* Left Column - Room Table */}
            <div className="w-full lg:w-[70%] bg-white shadow-sm border border-gray-100 overflow-hidden">
              <div className="grid grid-cols-[2fr_0.8fr_1.8fr_1fr] bg-[#382F2B] text-white text-[10px] font-bold uppercase tracking-wider p-4 border-b border-gray-200">
                <div>Room Type</div>
                <div className="text-center">Sleeps</div>
                <div>Price for {nights} nights | {adults} Adult {childrenCount} Child</div>
                <div className="text-center">Rooms</div>
              </div>

              {/* Room Content Row */}
              <div className="grid grid-cols-[2fr_0.8fr_1.8fr_1fr] border-b border-gray-100">
                {/* Room Info */}
                <div className="p-6 border-r border-gray-100 bg-gray-50/30">
                  <h3 className="text-lg font-serif mb-4">Luxury Glamping Tent</h3>
                  <div className="aspect-video mb-4 overflow-hidden rounded-sm shadow-md">
                    <img src="https://images.unsplash.com/photo-1533142262417-ad51619ff391?auto=format&fit=crop&q=80&w=600" alt="Double Room" className="w-full h-full object-cover" />
                  </div>
                  <div className="space-y-4">
                    <div className="p-3 bg-white border border-gray-100 rounded text-[10px] leading-relaxed italic text-[#63544B]">
                      "Our tents are designed for intimacy and connection with nature. Each room accommodates a maximum of 2 adults."
                    </div>
                    <ul className="text-[10px] space-y-3 text-[#63544B] font-light">
                      <li className="flex items-center gap-2"><i className="fa-solid fa-house-chimney text-[8px] text-luxury-tan"></i> <strong>Room Size:</strong> 32 m2</li>
                      <li className="flex items-center gap-2"><i className="fa-solid fa-ban-smoking text-[8px] text-luxury-tan"></i> <strong>Policy:</strong> Non-smoking</li>
                      <li className="flex items-center gap-2"><i className="fa-solid fa-bed text-[8px] text-luxury-tan"></i> <strong>Children:</strong> Free extra bed & breakfast for children under 5.</li>
                      <li className="flex items-start gap-2">
                        <i className="fa-solid fa-circle-check text-[8px] text-green-600 mt-1"></i>
                        <span>Infants under 5 stay free of charge in the same double bed or provided extra bed.</span>
                      </li>
                    </ul>
                  </div>
                </div>

                {/* Sub-Pricing Rows */}
                <div className="col-span-3 flex flex-col">
                  {PLANS.map((plan) => (
                    <div key={plan.id} className="grid grid-cols-[0.8fr_1.8fr_1fr] flex-1 border-b border-gray-100 items-center hover:bg-gray-50/50 transition-colors">
                      <div className="text-center text-[#382F2B] opacity-60">
                        <div className="flex flex-col items-center">
                          <i className="fa-solid fa-user-group text-lg mb-1"></i>
                          <span className="text-[9px] font-bold uppercase tracking-widest opacity-40">Max 2</span>
                        </div>
                      </div>
                      <div className="p-6">
                        <div className="flex items-baseline gap-1 mb-1">
                          <span className="text-[10px] font-bold opacity-60">USD</span>
                          <span className="text-xl font-bold">{plan.price}</span>
                        </div>
                        <p className="text-[9px] text-[#63544B] opacity-50 mb-2">Includes taxes and fees</p>
                        <div className="flex items-center gap-2 text-[10px] text-green-700 font-bold uppercase tracking-tight">
                          <i className="fa-solid fa-circle-check"></i>
                          <span>{plan.name}</span>
                        </div>
                      </div>
                      <div className="p-6 flex justify-center">
                        <RoomInput value={roomCounts[plan.id]} onChange={(val) => handleRoomChange(plan.id, val)} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Right Column - Your Booking Card */}
            <div className="w-full lg:w-[30%]">
              <div className="bg-white shadow-lg rounded-sm overflow-hidden border border-gray-100 sticky top-24">
                <div className="bg-[#382F2B] p-4 text-center">
                  <h4 className="text-[10px] font-bold text-white uppercase tracking-[0.2em]">Your Selection Summary</h4>
                </div>
                <div className="p-8">
                  <div className="mb-6 pb-6 border-b border-gray-100">
                    <p className="text-[10px] uppercase font-bold text-[#C19A74] tracking-widest mb-1">Stay Duration</p>
                    <p className="text-sm font-serif">{checkIn} — {checkOut}</p>
                    <p className="text-[10px] text-[#63544B] opacity-60 font-bold mt-1">{nights} Night(s)</p>
                  </div>

                  <div className="mb-6 pb-6 border-b border-gray-100">
                    <p className="text-[10px] uppercase font-bold text-[#C19A74] tracking-widest mb-1">Travelers</p>
                    <p className="text-sm font-serif">{adults} Adult(s), {childrenCount} Child(ren)</p>
                    {childrenCount > 0 && (
                      <p className="text-[9px] text-green-700 font-bold mt-2 italic flex items-center gap-1">
                        <i className="fa-solid fa-check"></i>
                        Child policy applied: Free bed & breakfast
                      </p>
                    )}
                  </div>

                  <div className="mb-8">
                    <p className="text-[10px] uppercase font-bold text-[#C19A74] tracking-widest mb-1">Room Allocation</p>
                    <p className="text-sm font-serif">{totalRoomsSelected} Room(s) selected</p>
                    <p className={`text-[10px] font-bold mt-1 uppercase tracking-tight ${isCapacitySufficient ? 'text-green-600' : 'text-red-500'}`}>
                      {isCapacitySufficient 
                        ? `Capacity: ${maxCapacity} adults (Sufficient)` 
                        : totalRoomsSelected === 0 ? 'Please select a room' : `Capacity: ${maxCapacity} adults (Insufficient)`
                      }
                    </p>
                  </div>

                  <ul className="space-y-4 mb-10 text-[10px] text-[#63544B] font-light uppercase tracking-widest">
                    <li className="flex items-center gap-3">
                      <i className="fa-solid fa-shield-halved text-luxury-tan"></i>
                      <span>Secure Reservation</span>
                    </li>
                    <li className="flex items-center gap-3">
                      <i className="fa-solid fa-headset text-luxury-tan"></i>
                      <span>24/7 Concierge</span>
                    </li>
                  </ul>

                  <button 
                    disabled={!isCapacitySufficient || totalRoomsSelected === 0}
                    onClick={handleProceedClick}
                    className={`w-full py-5 text-[11px] font-bold uppercase tracking-[0.3em] shadow-xl transition-all flex items-center justify-center gap-3 ${
                      isCapacitySufficient && totalRoomsSelected > 0
                        ? 'bg-luxury-tan text-white hover:bg-[#382F2B] active:scale-[0.98]'
                        : 'bg-gray-200 text-gray-400 cursor-not-allowed'
                    }`}
                  >
                    <i className="fa-solid fa-calendar-day"></i>
                    {totalRoomsSelected === 0 ? 'SELECT ROOMS' : 'PROCEED TO BOOK'}
                  </button>

                  <p className="mt-4 text-[9px] text-center text-[#63544B] opacity-40 font-bold uppercase tracking-widest">
                    Instant confirmation upon booking
                  </p>
                </div>
              </div>
            </div>

          </div>
