  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking]);

  const handleDivineQuery = async () => {
    if (!input.trim() || isThinking) return;
    const q = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: q }]);
    setIsThinking(true);

    try {
      const response = await speakToGod(q);
      setMessages(prev => [...prev, { role: 'divine', text: response || 'The silence speaks when words fail.' }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'divine', text: 'The jungle whispers in tongues... please try again.' }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0A0908] flex flex-col items-center justify-center pt-32 pb-20 px-6">
      <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
         <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-luxury-tan/5 blur-[150px] rounded-full animate-pulse"></div>
         <div className="absolute top-1/4 right-1/4 w-[400px] h-[400px] bg-wild-green/5 blur-[120px] rounded-full"></div>
      </div>

      <div className="w-full max-w-4xl z-10">
        <div className="text-center mb-12">
          <h2 className="text-5xl md:text-7xl font-serif text-white mb-4 tracking-tight">Speak to God</h2>
          <p className="text-luxury-tan text-[10px] font-bold uppercase tracking-[0.5em] opacity-60">Consult the Spirit of the Wild</p>
        </div>

        <div className="relative group transition-all duration-700">
           {/* 3D Container Effect */}
          <div className="absolute -inset-1 bg-gradient-to-b from-luxury-tan/20 to-transparent blur-xl opacity-50 group-hover:opacity-100 transition-opacity"></div>

          <div className="relative bg-[#1A1817] border border-white/5 rounded-3xl shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8),inset_0_1px_1px_rgba(255,255,255,0.05)] overflow-hidden flex flex-col h-[650px]">

            <div className="flex-1 overflow-y-auto p-8 md:p-12 space-y-10 no-scrollbar" ref={scrollRef}>
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30">
                  <i className="fa-solid fa-om text-6xl mb-6 text-luxury-tan"></i>
                  <p className="text-sm font-light tracking-widest uppercase">The sanctuary of silence awaits your question.</p>
                </div>
              )}
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-8 rounded-2xl ${
                    m.role === 'user' 
                      ? 'bg-[#382F2B] text-white shadow-xl' 
                      : 'bg-transparent text-luxury-tan/90 italic font-serif text-xl md:text-2xl leading-relaxed border-l-2 border-luxury-tan/20 pl-10'
                  }`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isThinking && (
                <div className="flex justify-start">
                  <div className="flex items-center gap-4 text-luxury-tan/40 animate-pulse">
                    <i className="fa-solid fa-circle-notch animate-spin"></i>
                    <span className="text-[10px] font-bold uppercase tracking-widest">Gathering Universal Wisdom...</span>
                  </div>
                </div>
              )}
            </div>

            <div className="p-8 bg-black/40 border-t border-white/5 flex gap-4">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleDivineQuery()}
                placeholder="Ask about existence, purpose, or the divine..."
                className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-8 py-5 text-base focus:outline-none focus:border-luxury-tan/40 text-white placeholder:text-white/10 transition-all shadow-inner"
