  onProceed: (rooms: SelectedRoom[]) => void;
}

const PLANS = [
  { id: 'plan1', name: 'Breakfast Included', price: 364 },
  { id: 'plan2', name: 'Breakfast & Lunch Included', price: 394 },
  { id: 'plan3', name: 'Full Board (B, L, D)', price: 422 },
  { id: 'plan4', name: 'All-inclusive Luxury', price: 754 },
];

const BookingSelection: React.FC<BookingSelectionProps> = ({ 
  checkIn, 
  checkOut, 
  adults, 
  childrenCount,
  onUpdateParams,
  onProceed
}) => {
  const [roomCounts, setRoomCounts] = useState<{ [key: string]: number }>({
    'plan1': 0, 'plan2': 0, 'plan3': 0, 'plan4': 0,
  });

  const handleRoomChange = (plan: string, val: number) => setRoomCounts(prev => ({ ...prev, [plan]: Math.max(0, val) }));
  const totalRoomsSelected = useMemo(() => Object.values(roomCounts).reduce((acc: number, curr: number) => acc + curr, 0), [roomCounts]);
  const calculateNights = () => {
    const start = new Date(checkIn); const end = new Date(checkOut);
    const diffTime = Math.abs(end.getTime() - start.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };
  const nights = calculateNights();
  const maxCapacity = totalRoomsSelected * 2;
  const isCapacitySufficient = maxCapacity >= adults;
