        <div className="grid grid-cols-1 lg:grid-cols-[1fr_1.8fr] gap-12">
          <div className="flex flex-col gap-10">
            <div className="bg-white/95 backdrop-blur-md shadow-2xl rounded-2xl overflow-hidden border border-emerald-100">
              <div className="bg-[#064E3B] px-10 py-6 flex items-center gap-3"><i className="fa-regular fa-calendar-check text-white text-xl"></i><h4 className="text-xl font-serif text-white">Your Booking Details</h4></div>
              <div className="p-10">
                <div className="grid grid-cols-2 gap-6 mb-8 bg-emerald-50/30 p-8 rounded-2xl border border-emerald-50 shadow-inner">
                  <div className="text-center"><p className="text-[10px] font-bold text-emerald-800 uppercase tracking-widest mb-3">CHECK-IN</p><p className="text-[14px] font-bold">{checkIn}</p></div>
                  <div className="text-center border-l border-emerald-100"><p className="text-[10px] font-bold text-emerald-800 uppercase tracking-widest mb-3">CHECK-OUT</p><p className="text-[14px] font-bold">{checkOut}</p></div>
                </div>
                <div className="flex items-center justify-between py-5 px-6 bg-emerald-100/50 text-emerald-900 rounded-2xl mb-10 border border-emerald-200"><span>Length of stay</span><span className="font-bold">{nights} nights</span></div>
              </div>
            </div>
            <div className="bg-white/95 shadow-2xl rounded-2xl overflow-hidden border border-emerald-100">
              <div className="bg-[#064E3B] px-10 py-8 flex items-center gap-4 shadow-md"><i className="fa-solid fa-wallet text-white text-xl"></i><h4 className="text-xl font-serif text-white">Price Summary</h4></div>
              <div className="p-10"><div className="flex items-center justify-between mb-3"><span className="text-3xl font-serif">Total:</span><span className="text-3xl font-serif font-bold text-emerald-600">USD {total.toFixed(2)}</span></div></div>
            </div>
          </div>

          <div className="flex flex-col gap-10">
            <div className="bg-white/95 backdrop-blur-md shadow-2xl rounded-2xl overflow-hidden border border-emerald-100">
              <div className="bg-[#064E3B] px-10 py-7 flex items-center gap-4"><i className="fa-solid fa-list-check text-white text-xl"></i><h4 className="text-xl font-serif text-white">Fill Your Details</h4></div>
              <div className="p-12">
                <form className="grid grid-cols-1 md:grid-cols-2 gap-12 mb-16">
                  {['First Name', 'Last Name', 'Email', 'Telephone'].map(label => (
                    <div key={label}><label className="text-[11px] font-bold text-emerald-800 block mb-4 uppercase">{label}</label><input required className="w-full border border-emerald-100 rounded-xl px-6 py-5 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 outline-none transition-all shadow-sm" type={label==='Email'?'email':'text'} /></div>
                  ))}
                </form>
                <button onClick={handleSubmit} className="w-full bg-[#064E3B] text-white py-7 rounded-2xl font-bold uppercase tracking-[0.5em] shadow-xl hover:bg-emerald-600 transition-all flex items-center justify-center gap-6">Confirm Booking</button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// Default export for Checkout
export default Checkout;
